using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class CostCenterRepository(NamaaDbContext db):ICostCenterRepository{public Task<bool>ExistsByCostCenterCodeAsync(string value,CancellationToken cancellationToken=default)=>db.CostCenters.AsNoTracking().AnyAsync(e=>e.CostCenterCode==value,cancellationToken);public Task<CostCenter?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.CostCenters.AsNoTracking().SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public Task<CostCenter?>FindForUpdateAsync(long id,CancellationToken cancellationToken=default)=>db.CostCenters.SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public async Task<IReadOnlyList<CostCenter>>GetAllAsync(CancellationToken cancellationToken=default)=>await db.CostCenters.AsNoTracking().OrderBy(e=>e.Id).ToListAsync(cancellationToken);public async Task AddAsync(CostCenter entity,CancellationToken cancellationToken=default)=>await db.CostCenters.AddAsync(entity,cancellationToken);}
